#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    // XOR reduction identity is false
    bool result = false;

    const int n = static_cast<int>(x.size());

    // Use OpenMP reduction with bitwise XOR on an integer accumulator,
    // then convert back to bool.
    unsigned int acc = 0;

    #pragma omp parallel for reduction(^ : acc)
    for (int i = 0; i < n; ++i) {
        acc ^= static_cast<unsigned int>(x[i]);
    }

    result = (acc != 0u);
    return result;
}
